    'search': '<SEARCH_TERM>',
    'start': '[OPTIONS] --description <DESCRIPTION> --project <PROJECT>',
    'status': '[OPTIONS]', 'stop': '[OPTIONS]',
}
# canonical option: (short spelling, long spelling, value name)
SPECS = {
    'file': ('f', None, 'FILE'), 'help': ('h', 'help', None),
    'version': ('V', 'version', None),
    'description': ('d', 'description', 'DESCRIPTION'),
    'project': ('p', 'project', 'PROJECT'), 'time': ('t', 'time', 'TIME'),
    'editor': ('e', None, 'editor'), 'number': ('n', 'number', 'NUMBER'),
    'date': ('d', 'date', 'DATE'), 'from': (None, 'from', 'FROM_DATE'),
    'to': (None, 'to', 'TO_DATE'), 'round': (None, 'round', 'round'),
    'current_week': (None, 'current_week', None),
    'last_week': (None, 'last_week', None), 'today': (None, 'today', None),
    'yesterday': (None, 'yesterday', None), 'no_grouping': (None, 'no_grouping', None),
    'current': ('c', 'current', None), 'no-quotes': ('n', 'no-quotes', None),
}
SCOPES = {
    '': ['file', 'version'], 'start': ['description', 'project', 'time'],
    'change': ['description', 'project', 'time'],
    'continue': ['description', 'project', 'time'], 'stop': ['time'],
    'edit': ['editor'], 'last': ['number'],
    'list': ['current_week', 'last_week', 'today', 'yesterday', 'no_grouping',
             'date', 'from', 'to', 'round', 'number', 'project'],
    'report': ['current_week', 'last_week', 'today', 'yesterday', 'date',
               'from', 'to', 'round', 'project'],
    'projects': ['current', 'no-quotes'], 'status': ['project'],
}
PROG = os.path.basename(sys.argv[0])
# Running the source directly is also useful while developing it.
if PROG == '__main__.py':
    PROG = 'executable'


def style(text, code):
    return '\x1b[' + str(code) + 'm' + text + RESET


def emit(text):
    sys.stdout.write(text)


def failure(text):
    sys.stderr.write('Error: ' + text + '\n')
    raise SystemExit(1)


def help_text(cmd=''):
    try:
        import zipfile
        if zipfile.is_zipfile(sys.argv[0]):
            with zipfile.ZipFile(sys.argv[0]) as z:
                texts = json.loads(z.read('help.json'))
        else:
            with open(os.path.join(os.path.dirname(__file__), 'help.json'), encoding='utf-8') as f:
                texts = json.load(f)
    except (OSError, ValueError):
        texts = {}
    text = texts.get(cmd, texts.get('', ''))
    text = text.replace('executable', PROG)
    text = text.replace('[env: BARTIB_FILE=]', '[env: BARTIB_FILE=' + os.getenv('BARTIB_FILE', '') + ']')
    return text.replace('[env: EDITOR=]', '[env: EDITOR=' + os.getenv('EDITOR', '') + ']')


def option_label(key):
    short, long, value = SPECS[key]
    return ('--' + long if long else '-' + short) + (' <' + value + '>' if value else '')


def usage(cmd='', seen=None, full=False):
    base = PROG + (' ' + cmd if cmd else '')
    if cmd in ('', 'start', 'search') or full or not seen:
        return base + (' ' + USAGES.get(cmd, '') if USAGES.get(cmd, '') else '')
    keys = [k for k in seen if k in SPECS and k not in ('help', 'version', 'file')]
    if keys:
        return base + ' ' + ' '.join(option_label(k) for k in sorted(keys))
    return base + (' ' + USAGES.get(cmd, '') if USAGES.get(cmd, '') else '')


def cli_error(message, cmd='', seen=None, full=False):
    sys.stderr.write('error: ' + message + '\n\nUSAGE:\n    ' + usage(cmd, seen, full)
                     + '\n\nFor more information try --help\n')
    raise SystemExit(1)


def jaro_winkler(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    span = max(len(a), len(b)) // 2 - 1
    span = max(span, 0)
    a_used = [False] * len(a)
    b_used = [False] * len(b)
    count = 0
    for i, ch in enumerate(a):
        for j in range(max(0, i - span), min(len(b), i + span + 1)):
            if not b_used[j] and ch == b[j]:
                a_used[i] = b_used[j] = True
                count += 1
                break
    if not count:
        return 0.0
    aa = [a[i] for i in range(len(a)) if a_used[i]]
    bb = [b[i] for i in range(len(b)) if b_used[i]]
    trans = sum(x != y for x, y in zip(aa, bb)) / 2
    score = (count / len(a) + count / len(b) + (count - trans) / count) / 3
    if score > 0.7:
        prefix = 0
        for x, y in zip(a[:4], b[:4]):
            if x != y:
                break
            prefix += 1
        score += prefix * 0.1 * (1 - score)
    return score


def suggest(arg, candidates):
    matches = [(jaro_winkler(arg, c), c) for c in candidates]
    matches = [(s, c) for s, c in matches if s > 0.8]
    return max(matches)[1] if matches else None


def unknown(arg, cmd, seen, long_options=None, no_sub_suggestions=False):
    msg = "Found argument '" + arg + "' which wasn't expected, or isn't valid in this context"
    if cmd == '' and not arg.startswith('-') and not no_sub_suggestions:
        hint = suggest(arg, COMMANDS)
        if hint:
            msg = ("The subcommand '" + arg + "' wasn't recognized\n\tDid you mean '" + hint + "'?\n\n"
                   "If you believe you received this message in error, try re-running with '" + PROG + ' -- ' + arg + "'")
    elif arg.startswith('--') and long_options:
        hint = suggest(arg[2:], long_options)
        if hint:
            msg += '\n\tDid you mean ' + style('--', '32') + style(hint, '32') + '?'
            seen = dict(seen)
            seen[long_options[hint]] = True
    cli_error(msg, cmd, seen)


def parse_cli(argv):
    cmd = ''
    seen = {}
    root = {}
    pos = []
    after_dash = False
    pending = None
    i = 0
    while i < len(argv):
        arg = argv[i]
        i += 1
        keys = ['help'] + SCOPES.get(cmd, [])
        short_map = {SPECS[k][0]: k for k in keys if SPECS[k][0]}
        long_map = {SPECS[k][1]: k for k in keys if SPECS[k][1]}
        if not after_dash and arg == '--':
            after_dash = True
            continue
        if not after_dash and arg.startswith('-') and arg != '-':
            opts = []
            if arg.startswith('--'):
                name, equal, value = arg[2:].partition('=')
                if name not in long_map:
                    unknown('--' + name, cmd, seen, long_map)
                opts.append((long_map[name], value if equal else None, bool(equal)))
            else:
                cluster = arg[1:]
                j = 0
                while j < len(cluster):
                    char = cluster[j]
                    j += 1
                    if char not in short_map:
                        unknown('-' + char, cmd, seen, long_map)
                    key = short_map[char]
                    if SPECS[key][2] and j < len(cluster):
                        val = cluster[j:]
                        if val.startswith('='):
                            val = val[1:]
                        opts.append((key, val, True))
                        break
                    opts.append((key, None, False))
                    if SPECS[key][2]:
                        break
            for key, value, supplied in opts:
                if key == 'help':
                    emit(help_text(cmd))
                    raise SystemExit(0)
                if key == 'version':
                    emit('bartib 1.1.0\n')
                    raise SystemExit(0)
                if key in seen:
                    cli_error("The argument '" + option_label(key)
                              + "' was provided more than once, but cannot be used multiple times", cmd, seen)
                if SPECS[key][2]:
                    if not supplied:
                        if i < len(argv) and (not argv[i].startswith('-') or argv[i] == '-'):
                            value = argv[i]
                            i += 1
                        else:
                            value = None
                            pending = key
                    seen[key] = value
                else:
                    seen[key] = True
        else:
            if not cmd and arg in COMMANDS:
                if arg == 'help':
                    trail = argv[i:]
                    target = trail[0] if trail else ''
                    if target in COMMANDS and target != 'help' and len(trail) == 1:
                        emit(help_text(target))
                        raise SystemExit(0)
                    if not trail:
                        emit(help_text())
                        raise SystemExit(0)
                    unrecognized = trail[-1] if len(trail) > 1 else target
                    sys.stderr.write("error: The subcommand '" + unrecognized + "' wasn't recognized\n\nUSAGE:\n\t"
                                     + PROG + ' help <subcommands>...\n\nFor more information try --help\n')
                    raise SystemExit(1)
                root, seen = seen, {}
                cmd = arg
                after_dash = False
            elif cmd in ('search', 'continue') and not pos:
                pos.append(arg)
            else:
                unknown(arg, cmd, seen, long_map, after_dash)
    if not cmd:
        sys.stderr.write(help_text())
        raise SystemExit(1)
    if cmd == 'start':
        missing = [k for k in ['description', 'project'] if k not in seen]
        if missing:
            cli_error('The following required arguments were not provided:\n'
                      + '\n'.join('    ' + option_label(k) for k in missing), cmd, seen)
    if pending is not None:
        cli_error("The argument '" + option_label(pending) + "' requires a value but none was supplied", cmd, seen)
    # Day and week selectors cannot be combined with explicit ranges.
    priority = ['date', 'from', 'to', 'current_week', 'last_week', 'today', 'yesterday']
    for a in priority:
        if a not in seen:
            continue
        for b in priority:
            if b == a or b not in seen:
                continue
            if {a, b} <= {'from', 'to'}:
                continue
            cli_error("The argument '" + option_label(a) + "' cannot be used with '" + option_label(b) + "'", cmd, seen)
    file = root.get('file', os.getenv('BARTIB_FILE'))
    return cmd, seen, pos, file


class ParseError(Exception):
    pass


class DateParser:
    """Numeric date fields, accepting the loose padding of the CLI's format."""
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def number(self, width, lower, upper, signed=False):
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1
        if self.pos == len(self.text):
            raise ParseError('premature end of input')
        start = self.pos
        sign = ''
        if signed and self.text[self.pos] in '+-':
            sign = self.text[self.pos]
            self.pos += 1
            width = 12
        end = self.pos
        while end < len(self.text) and end - self.pos < width and '0' <= self.text[end] <= '9':
            end += 1
        if end == self.pos:
            raise ParseError('input contains invalid characters')
        value = int(sign + self.text[self.pos:end])
        self.pos = end
        if not lower <= value <= upper:
            raise ParseError('input is out of range')
        return value

    def literal(self, value):
        if self.pos == len(self.text):
            raise ParseError('premature end of input')
        if not self.text.startswith(value, self.pos):
            raise ParseError('input contains invalid characters')
        self.pos += len(value)

    def space(self):
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1

    def date_fields(self):
        year = self.number(4, -262144, 262143, True)
        self.literal('-')
        month = self.number(2, 1, 12)
        self.literal('-')
        day = self.number(2, 1, 31)
        return year, month, day

    def time_fields(self, seconds=False):
        hour = self.number(2, 0, 23)
        self.literal(':')
        minute = self.number(2, 0, 59)
        second = 0
        if seconds:
            self.literal(':')
            second = self.number(2, 0, 60)
        return hour, minute, second

    def end(self):
        if self.pos != len(self.text):
            raise ParseError('trailing input')


def parse_date(text):
    p = DateParser(text)
    values = p.date_fields()
    p.end()
    try:
        return dt.date(*values)
    except ValueError:
        raise ParseError('input is out of range')


def parse_clock(text):
    p = DateParser(text)
    values = p.time_fields()
    p.end()
    return values


def nearest_minute(value):
    return (value + dt.timedelta(seconds=30)).replace(second=0, microsecond=0)


def parse_timestamp(text):
    def attempt(seconds):
        p = DateParser(text)
        date = p.date_fields()
        p.space()
        clock = p.time_fields(seconds)
        p.end()
        try:
            base = dt.datetime(*date, *clock)
        except ValueError:
            if clock[2] == 60:
                try:
                    base = dt.datetime(*date, clock[0], clock[1], 59) + dt.timedelta(seconds=1)
                except ValueError:
                    raise ParseError('input is out of range')
            else:
                raise ParseError('input is out of range')
        return base
    try:
        return attempt(False)
    except ParseError:
        value = attempt(True)
        sys.stderr.write(PRECISION_WARNING)
        return nearest_minute(value)


def parse_option_date(options, key):
    text = options.get(key)
    if text is None:
        return None
    try:
        return parse_date(text)
    except ParseError as err:
        flag = '-d/--date' if key == 'date' else '--' + key
        emit('Can not parse "' + text + '" as date. Argument for ' + flag + ' is ignored (' + str(err) + ')\n')
        return None


def parse_option_time(options, now):
    text = options.get('time')
    if text is None:
        return nearest_minute(now)
    try:
        h, m, s = parse_clock(text)
        return now.replace(hour=h, minute=m, second=0, microsecond=0)
    except ParseError as err:
        emit('Can not parse "' + text + '" as time. Argument for -t/--time is ignored (' + str(err) + ')\n')
        return nearest_minute(now)


def parse_number(text, fallback=None):
    if text is None:
        return fallback
    if re.fullmatch(r'\+?[0-9]+', text):
        value = int(text)
        if value <= 18446744073709551615:
            return value
    emit('Can not parse "' + text + '" as number. Argument for -n/--number is ignored\n')
    return fallback


def parse_round(text):
    if text is None or len(text) < 2:
        return None
    prefix, unit = text[:-1], text[-1]
    if not re.fullmatch(r'[+-]?[0-9]+', prefix):
        return None
    value = int(prefix)
    if not -(2**63) <= value < 2**63:
        return None
    if unit == 'h':
        return value * 3600
    if unit == 'm':
        return value * 60
    emit('Can not parse "' + text + '" as duration. Argument for --round is ignored\n')
    return None


def format_stamp(value):
    return f'{value.year:04d}-{value.month:02d}-{value.day:02d} {value.hour:02d}:{value.minute:02d}'


def format_clock(value):
    return f'{value.hour:02d}:{value.minute:02d}'


def format_duration(seconds):
    minutes = math.trunc(seconds / 60)
    if minutes < 1:
        return '<1m'
    if minutes < 60:
        return f'{minutes:02d}m'
    return f'{minutes // 60}h {minutes % 60:02d}m'


@dataclass
class Activity:
    start: dt.datetime
    end: object
    project: str
    description: str
    line: int = 0

    def duration(self, now):
        return ((self.end if self.end is not None else now) - self.start).total_seconds()

    def serialize(self):
        def escape(value):
            return value.replace('\\', '\\\\').replace('|', '\\|')
        times = format_stamp(self.start)
        if self.end is not None:
            times += ' - ' + format_stamp(self.end)
        return times + ' | ' + escape(self.project) + ' | ' + escape(self.description)

    def identify(self):
        return '"' + self.description + '" (' + self.project + ')'


@dataclass
class LogLine:
    raw: str
    activity: object
    error: object
    number: int


def split_fields(text):
    fields = []
    part = ''
    escaped = False
    for char in text:
        if escaped:
            part += char
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(part)
            part = ''
        else:
            part += char
    if part:
        fields.append(part)
    return fields


def parse_line(raw, number):
    fields = split_fields(raw)
    if len(fields) < 2:
        return LogLine(raw.strip(), None, 'could not parse activity', number)
    times = fields[0].strip().split(' - ')
    try:
        start = parse_timestamp(times[0].strip())
        end = parse_timestamp(times[1].strip()) if len(times) > 1 else None
    except ParseError:
        return LogLine(raw.strip(), None, 'could not parse date or time of activity', number)
    act = Activity(start, end, fields[1].strip(), fields[2].strip() if len(fields) > 2 else '', number)
    return LogLine(raw.strip(), act, None, number)


def os_error(err):
    return os.strerror(err.errno) + f' (os error {err.errno})'


def read_log(file, allow_missing=False):
    try:
        handle = open(file, 'rb')
    except IsADirectoryError:
        return []
    except OSError as err:
        if allow_missing and err.errno == 2:
            return []
        failure('Could not read from file: ' + file + '\n\nCaused by:\n    ' + os_error(err))
    lines = []
    with handle:
        try:
            for number, raw in enumerate(handle, 1):
                try:
                    text = raw.decode('utf-8')
                except UnicodeDecodeError:
                    continue
                if text.endswith('\n'):
                    text = text[:-1]
                    if text.endswith('\r'):
                        text = text[:-1]
                lines.append(parse_line(text, number))
        except OSError:
            pass
    return lines


def write_log(file, lines):
    try:
        with open(file, 'w', encoding='utf-8', newline='') as handle:
            handle.write(''.join(line + '\n' for line in lines))
    except OSError as err:
        failure('Could not write to file: ' + file + '\n\nCaused by:\n    ' + os_error(err))


def activities(lines, warn=True):
    result = []
    for line in lines:
        if line.activity is not None:
            result.append(line.activity)
        elif warn:
            emit(f'Warning: Ignoring line {line.number}. Please see `bartib check` for further information\n')
    return result


def recent(acts):
    unique = []
    found = set()
    for act in reversed(sorted(acts, key=lambda a: a.start)):
        key = (act.description, act.project)
        if key not in found:
            found.add(key)
            unique.append(act)
    return unique


def round_stamp(stamp, interval):
    epoch = dt.datetime(1970, 1, 1)
    if not interval:
        return epoch
    value = (stamp - epoch).total_seconds() / interval
    multiple = math.floor(value + 0.5) if value >= 0 else math.ceil(value - 0.5)
    try:
        return epoch + dt.timedelta(seconds=multiple * interval)
    except (ValueError, OverflowError):
        return epoch


def select_activities(acts, date=None, start=None, end=None, project=None, number=None, rounding=None):
    selected = [a for a in acts if (project is None or a.project == project)
                and (date is None or a.start.date() == date)
                and (start is None or a.start.date() >= start)
                and (end is None or a.start.date() <= end)]
    selected.sort(key=lambda a: a.start)
    if number is not None:
        selected = selected[-number:] if number else []
    if rounding is not None:
        selected = [replace(a, start=round_stamp(a.start, rounding),
                            end=round_stamp(a.end, rounding) if a.end is not None else None) for a in selected]
    return selected


def filter_options(options, today):
    date = parse_option_date(options, 'date')
    start = parse_option_date(options, 'from')
    end = parse_option_date(options, 'to')
    if options.get('today'):
        date = today
    if options.get('yesterday'):
        date = today - dt.timedelta(days=1)
    monday = today - dt.timedelta(days=today.weekday())
    if options.get('current_week'):
        start, end = monday, monday + dt.timedelta(days=6)
    if options.get('last_week'):
        start, end = monday - dt.timedelta(days=7), monday - dt.timedelta(days=1)
    return date, start, end


def display_width(char):
    if unicodedata.combining(char) or unicodedata.category(char) in ('Cc', 'Cf'):
        return 0
    return 2 if unicodedata.east_asian_width(char) in ('W', 'F') else 1


def wrap_cell(text, width):
    # Most cells fit naturally. Wide glyphs can require additional physical rows.
    chunks = []
    rest = text
    while rest:
        count = 0
        end = 0
        last_space = None
        for i, ch in enumerate(rest):
            w = display_width(ch)
            if count + w > width:
                break
            count += w
            end = i + 1
            if ch.isspace() and ch not in ('\u00a0', '\u202f'):
                last_space = i
        if end == len(rest):
            chunks.append(rest)
            break
        if last_space is not None and last_space > 0:
            chunks.append(rest[:last_space])
            rest = rest[last_space + 1:]
        else:
            end = max(end, 1)
            chunks.append(rest[:end])
            rest = rest[end:]
    return chunks or ['']


def table_widths(headers, rows):
    return [max([len(h)] + [len(row[i]) for row in rows]) for i, h in enumerate(headers)]


def table_row(row, widths, code=None):
    cells = [wrap_cell(cell, width) for cell, width in zip(row, widths)]
    output = ''
    for physical in range(max(map(len, cells))):
        for parts, width in zip(cells, widths):
            cell = parts[physical] if physical < len(parts) else ''
            cell += NBSP * max(0, width - len(cell))
            output += (style(cell, code) if code else cell) + ' '
        output += '\n'
    return output


def print_last(acts, limit=None, term=None):
    rec = recent(acts)
    entries = list(enumerate(rec))
    if term is not None:
        term = term.lower()
        entries = [(n, a) for n, a in entries if term in a.description.lower() or term in a.project.lower()]
    if limit is not None:
        entries = entries[:limit]
    if not entries:
        emit('No matching activities found\n' if term is not None else 'No activities have been tracked yet\n')
        return
    rows = [[f'[{n}]', a.description, a.project] for n, a in reversed(entries)]
    headers = [' #', 'Description', 'Project']
    widths = table_widths(headers, rows)
    emit('\n' + table_row(headers, widths, '4'))
    for row in rows:
        emit(table_row(row, widths))
    emit('\n')


def print_current(acts, now):
    acts = [a for a in acts if a.end is None]
    if not acts:
        emit('No Activity is currently running\n')
        return
    headers = ['Started At', 'Description', 'Project', 'Duration']
    rows = [[format_stamp(a.start), a.description, a.project, format_duration(a.duration(now))] for a in acts]
    widths = table_widths(headers, rows)
    emit('\n' + table_row(headers, widths, '4'))
    for row in rows:
        emit(table_row(row, widths))
    emit('\n')


def print_list(acts, now, grouped=True, single_date=False):
    if not acts:
        emit('No activity to display\n')
        return
    rows = []
    for a in acts:
        begin = format_clock(a.start) if grouped or single_date else format_stamp(a.start)
        finish = '-' if a.end is None else (format_clock(a.end) if a.start.date() == a.end.date() else format_stamp(a.end))
        rows.append([begin, finish, a.description, a.project, format_duration(a.duration(now))])
    headers = ['Started', 'Stopped', 'Description', 'Project', 'Duration']
    widths = table_widths(headers, rows)
    emit('\n' + table_row(headers, widths, '4'))
    previous = None
    for a, row in zip(acts, rows):
        if grouped and not single_date and a.start.date() != previous:
            previous = a.start.date()
            total = sum(x.duration(now) for x in acts if x.start.date() == previous)
            emit('\n' + style(str(previous) + '\t' + format_duration(total), '1') + '\n')
        code = '32' if a.end is None else ('33' if a.start.date() != a.end.date() else None)
        emit(table_row(row, widths, code))
    emit('\n')


def print_report(acts, now):
    groups = {}
    for a in acts:
        values = groups.setdefault(a.project, {})
        values[a.description] = values.get(a.description, 0) + a.duration(now)
    label_width = max([5] + [len(p) for p in groups] + [len(d) + 4 for v in groups.values() for d in v])
    duration_width = max([0] + [len(format_duration(t)) for v in groups.values() for t in v.values()]
                         + [len(format_duration(sum(v.values()))) for v in groups.values()])
    emit('\n')
    total = 0
    for project in sorted(groups):
        values = groups[project]
        subtotal = sum(values.values())
        total += subtotal
        emit(style(project + '.' * (label_width - len(project)) + ' '
                   + format_duration(subtotal).rjust(duration_width), '1') + '\n')
        for description in sorted(values):
            label = '    ' + description
            emit(label + '.' * (label_width - len(label)) + ' '
                 + format_duration(values[description]).rjust(duration_width) + '\n')
        emit('\n')
    emit(style('Total' + '.' * (label_width - 5) + ' ' + format_duration(total), '1') + '\n\n')


def print_status(acts, now, project=None):
    if project is not None:
        acts = [a for a in acts if a.project == project]
    emit(style('\n =======', '2'))
    if project is None:
        emit(style(' Status for ', '3') + style('ALL', '1') + style(' projects ', '3'))
    else:
        emit(style(' Status for project: ', '3') + style(project, '1'))
    emit(style(' ======= \n', '2') + style('\n  NOW: ', '2;3'))
    current = [a for a in acts if a.end is None]
    if current:
        a = current[-1]
        emit(style(a.description, '1;32'))
        if project is None:
            emit(style(' on ', '2;3') + style(a.project, '3'))
        emit(style(' ...... ', '2') + style(format_duration(a.duration(now)), '1') + style('\n\n', '2'))
    else:
        emit(style(' NO Activity\n\n', '1'))
    today = now.date()
    monday = today - dt.timedelta(days=today.weekday())
    for label, start in [('Today', today), ('Current week', monday), ('Current month', today.replace(day=1))]:
        duration = sum(a.duration(now) for a in acts if start <= a.start.date() <= today)
        emit(style(' ', '3') + style(' ' + label + '.' * (30 - len(label)) + ' ', '2;3')
             + style(format_duration(duration), '1') + style('\n', '3'))
    emit('\n')


def check_log(lines):
    errors = [line for line in lines if line.error]
    if not errors:
        emit('All lines in the file have been successfully parsed as activities.\n')
    else:
        emit(f'Found {len(errors)} line(s) with parsing errors\n')
        for line in errors:
            emit('\n' + line.raw + '\n  -> ' + line.error + f' (Line: {line.number})\n')


def sanity(acts):
    latest_end = None
    count = 0
    for a in sorted(acts, key=lambda a: a.start):
        warnings = []
        if a.end is not None and a.end < a.start:
            warnings.append('Activity has negative duration')
        if latest_end is not None and a.start < latest_end:
            warnings.append('Activity started before another activity ended')
        if warnings:
            count += 1
            emit('\n'.join(warnings) + '\n' + a.description + ' (Started: ' + format_stamp(a.start)
                 + ', Ended: ' + (format_stamp(a.end) if a.end is not None else '--')
                 + f', Line: {a.line})\n\n')
        if a.end is not None and (latest_end is None or a.end > latest_end):
            latest_end = a.end
    if not count:
        emit('No unusual activities.\n')


def update_log(cmd, lines, file, options, when, new=None):
    output = []
    for line in lines:
        a = line.activity
        if a is None or a.end is not None:
            output.append(line.raw)
            continue
        if cmd == 'cancel':
            emit('Canceled activity: ' + a.identify() + ' started at ' + format_stamp(a.start) + '\n')
            continue
        if cmd == 'change':
            if not any(k in options for k in ('description', 'project', 'time')):
                output.append(line.raw)
                continue
            b = replace(a, project=options.get('project', a.project),
                        description=options.get('description', a.description),
                        start=when if 'time' in options else a.start)
            emit('Changed activity: ' + b.identify() + ' started at ' + format_stamp(b.start) + '\n')
        else:
            b = replace(a, end=when)
            emit('Stopped activity: ' + a.identify() + ' started at ' + format_stamp(a.start)
                 + ' (' + format_duration(b.duration(when)) + ')\n')
        output.append(b.serialize())
    if new is not None:
        emit('Started activity: ' + new.identify() + ' at ' + format_stamp(new.start) + '\n')
        output.append(new.serialize())
    write_log(file, output)


def main(argv):
    cmd, options, positional, file = parse_cli(argv)
    if file is None:
        failure(MISSING_FILE)
    now = dt.datetime.now()
    if cmd == 'edit':
        editor = options.get('editor', os.getenv('EDITOR'))
        if editor is None:
            failure('editor command is missing')
        try:
            subprocess.run([editor, file])
        except OSError as err:
            failure(os_error(err))
        return
    if cmd in ('start', 'stop', 'cancel', 'change', 'continue'):
        when = parse_option_time(options, now) if cmd != 'cancel' else nearest_minute(now)
        number = parse_number(positional[0] if positional else None, 0) if cmd == 'continue' else 0
        lines = read_log(file, cmd == 'start')
        new = None
        if cmd == 'start':
            new = Activity(when, None, options['project'], options['description'])
        elif cmd == 'continue':
            rec = recent(activities(lines))
            if not rec:
                failure('No activity has been started before.')
            if number >= len(rec):
                failure(f'Less than {number} distinct activities have been logged yet')
            a = rec[number]
            new = Activity(when, None, options.get('project', a.project), options.get('description', a.description))
        update_log(cmd, lines, file, options, when, new)
        return
    number = None
    if cmd in ('list', 'last'):
        number = parse_number(options.get('number'), 10 if cmd == 'last' else None)
    date, start, end = (None, None, None)
    rounding = None
    if cmd in ('list', 'report'):
        date, start, end = filter_options(options, now.date())
        rounding = parse_round(options.get('round'))
    lines = read_log(file)
    if cmd == 'check':
        check_log(lines)
        return
