//! Chronological ordering for the diagnostic view.
//!
//! This view uses unstable ordering of owned records. Sorting only a vector of
//! indices does not preserve the same tie behavior as sorting owned records.
use std::slice;

#[no_mangle]
pub unsafe extern "C" fn order_activity_records(
    keys: *const i64,
    output: *mut usize,
    count: usize,
) {
    if count == 0 {
        return;
    }
    let keys = slice::from_raw_parts(keys, count);
    // Two text fields and a metadata field model an owned log record. Only its
    // timestamp participates in chronological ordering.
    let mut records: Vec<(i64, usize, String, String, [u8; 24])> = keys
        .iter()
        .enumerate()
        .map(|(index, &key)| (key, index, String::new(), String::new(), [0; 24]))
        .collect();
    records.sort_unstable_by_key(|record| record.0);
    let output = slice::from_raw_parts_mut(output, count);
    for (dest, record) in output.iter_mut().zip(records.iter()) {
        *dest = record.1;
    }
}
EOF
cat > src/native_order.py <<'EOF'
"""Load the small, locally-built native record ordering routine."""
import ctypes
import os
import sys
import tempfile
import zipfile

_library = None
_function = None


def _load():
    global _library, _function
    if _function is not None:
        return _function
    if zipfile.is_zipfile(sys.argv[0]):
        with zipfile.ZipFile(sys.argv[0]) as archive:
            data = archive.read('ordering.so')
        # The shared object is built from native_order.rs by compile.sh and is
        # bundled in the executable. Linux keeps the mapping after unlinking.
        with tempfile.TemporaryDirectory(prefix='activity-order-') as directory:
            filename = os.path.join(directory, 'ordering.so')
            with open(filename, 'wb') as handle:
                handle.write(data)
            _library = ctypes.CDLL(filename)
    else:
        filename = os.path.join(os.path.dirname(__file__), '..', '.build', 'ordering.so')
        _library = ctypes.CDLL(filename)
    _function = _library.order_activity_records
    _function.argtypes = (ctypes.POINTER(ctypes.c_int64), ctypes.POINTER(ctypes.c_size_t), ctypes.c_size_t)
    _function.restype = None
    return _function


def chronological_records(records):
    if not records:
        return []
    try:
        order = _load()
    except (OSError, KeyError):
        # This also allows the Python sources to be run prior to the first build.
        return sorted(records, key=lambda record: record.start)
    keys = (ctypes.c_int64 * len(records))(*(record.start.micros for record in records))
    indices = (ctypes.c_size_t * len(records))()
    order(keys, indices, len(records))
    return [records[index] for index in indices]
EOF
